// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { evolvePath } from "@remotion/paths";

import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();
const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type DroppingCoinsProps = Record<string, any>;

const BUILDING_PATH =
  "M 50 10 L 50 30 M 50 12 L 65 12 L 65 22 L 50 22 M 15 50 L 50 25 L 85 50 Z M 10 50 L 90 50 M 25 50 L 25 85 M 41 50 L 41 85 M 59 50 L 59 85 M 75 50 L 75 85 M 20 85 L 80 85 M 15 90 L 85 90 M 10 95 L 90 95";
const POCKET_PATH =
  "M 10 20 L 90 20 L 90 60 C 90 85 70 100 50 100 C 30 100 10 85 10 60 Z M 10 30 L 90 30";
const STITCH_PATH =
  "M 18 28 L 18 58 C 18 78 34 90 50 90 C 66 90 82 78 82 58 L 82 28";

const DroppingCoins: React.FC<DroppingCoinsProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 3,
  primaryColor = "#ffffff",
  accentColor = "#ff2a2a",
  coinSymbol = "$",
  coinFontFamily = "Space Grotesk",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const fontMap = {
    "Space Grotesk": spaceGroteskFamily,
    Inter: interFamily,
    "Roboto Mono": robotoMonoFamily,
  };
  const fontFamily = fontMap[coinFontFamily];

  const centerX = width / 2;
  const centerY = height / 2;

  // Timings
  const buildProgress = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const pocketProgress = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const stitchOpacity = interpolate(pocketProgress, [0.5, 1], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const arrowProgress = interpolate(frame, [15, 25], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const coinStarts = [25, 35, 45];
  const coinLands = [
    centerY + 220 * s,
    centerY + 200 * s,
    centerY + 180 * s,
  ];

  const coinY = (index: number) => {
    return spring({
      frame: frame - coinStarts[index],
      fps,
      config: { damping: 12, mass: 0.8 },
      from: centerY, // Center of arrow tip
      to: coinLands[index],
    });
  };

  const sparkProgress = interpolate(frame, [60, 75], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const sparkScale = interpolate(sparkProgress, [0, 1], [0.5, 1.2]);
  const sparkOpacity = interpolate(sparkProgress, [0, 0.2, 1], [0, 1, 0]);

  const buildingEvolution = evolvePath(buildProgress, BUILDING_PATH);
  const pocketEvolution = evolvePath(pocketProgress, POCKET_PATH);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      
      {/* Arrow (Reveals downwards from the building base) */}
      <div
        style={{
          position: "absolute",
          left: centerX - 50 * s,
          top: centerY - 100 * s,
          width: 100 * s,
          height: 100 * s,
          opacity: arrowProgress > 0 ? arrowProgress : 0,
          transform: `scaleY(${arrowProgress})`,
          transformOrigin: "top center",
          transition: "none",
        }}
      >
        <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%" }}>
          <defs>
            <linearGradient id="arrowGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={accentColor} stopOpacity={0} />
              <stop offset="100%" stopColor={accentColor} stopOpacity={1} />
            </linearGradient>
          </defs>
          <path d="M 35 0 L 65 0 L 65 50 L 85 50 L 50 100 L 15 50 L 35 50 Z" fill="url(#arrowGrad)" />
        </svg>
      </div>

      {/* Building */}
      <div
        style={{
          position: "absolute",
          left: centerX - 150 * s,
          top: centerY - 400 * s,
          width: 300 * s,
          height: 300 * s,
          opacity: buildProgress > 0 ? 1 : 0,
          transition: "none",
        }}
      >
        <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%" }}>
          <path
            d={BUILDING_PATH}
            fill="none"
            stroke={primaryColor}
            strokeWidth={3}
            strokeLinejoin="round"
            strokeLinecap="round"
            strokeDasharray={buildingEvolution.strokeDasharray}
            strokeDashoffset={buildingEvolution.strokeDashoffset}
            style={{ transition: "none" }}
          />
        </svg>
      </div>

      {/* Coins Wrapper (Clips coins as they enter the pocket) */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: width,
          height: centerY + 210 * s, // Exactly matches the pocket's top opening line
          overflow: "hidden",
          transition: "none",
        }}
      >
        {coinStarts.map((startFrame, i) => {
          const y = coinY(i);
          const opacity = frame >= startFrame ? 1 : 0;
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: centerX - 40 * s,
                top: y - 40 * s,
                width: 80 * s,
                height: 80 * s,
                opacity,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                transition: "none",
              }}
            >
              <svg viewBox="0 0 100 100" style={{ position: "absolute", width: "100%", height: "100%" }}>
                <circle cx="50" cy="50" r="45" fill={backgroundColor} stroke={accentColor} strokeWidth="6" />
              </svg>
              <div
                style={{
                  color: accentColor,
                  fontFamily,
                  fontSize: 40 * s,
                  zIndex: 1,
                  fontWeight: "bold",
                  lineHeight: 1,
                  transition: "none",
                }}
              >
                {coinSymbol}
              </div>
            </div>
          );
        })}
      </div>

      {/* Pocket */}
      <div
        style={{
          position: "absolute",
          left: centerX - 150 * s,
          top: centerY + 150 * s,
          width: 300 * s,
          height: 300 * s,
          opacity: pocketProgress > 0 ? 1 : 0,
          transition: "none",
        }}
      >
        <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%" }}>
          <path
            d={POCKET_PATH}
            fill="none"
            stroke={primaryColor}
            strokeWidth={3}
            strokeLinejoin="round"
            strokeLinecap="round"
            strokeDasharray={pocketEvolution.strokeDasharray}
            strokeDashoffset={pocketEvolution.strokeDashoffset}
            style={{ transition: "none" }}
          />
          <path
            d={STITCH_PATH}
            fill="none"
            stroke={primaryColor}
            strokeWidth={2}
            strokeDasharray="4 4"
            opacity={stitchOpacity}
            style={{ transition: "none" }}
          />
        </svg>
      </div>

      {/* Sparks */}
      <div
        style={{
          position: "absolute",
          left: centerX - 100 * s,
          top: centerY + 130 * s,
          width: 200 * s,
          height: 100 * s,
          opacity: sparkOpacity,
          transform: `scale(${sparkScale})`,
          transformOrigin: "center bottom",
          transition: "none",
        }}
      >
        <svg viewBox="0 0 200 100" style={{ width: "100%", height: "100%" }}>
          <g stroke={accentColor} strokeWidth={4} strokeLinecap="round">
            <line x1="40" y1="70" x2="20" y2="40" vectorEffect="non-scaling-stroke" />
            <line x1="70" y1="40" x2="50" y2="10" vectorEffect="non-scaling-stroke" />
            <line x1="130" y1="40" x2="150" y2="10" vectorEffect="non-scaling-stroke" />
            <line x1="160" y1="70" x2="180" y2="40" vectorEffect="non-scaling-stroke" />
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default DroppingCoins;